        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = corners[0]
        best = -1
        for c in corners:
            d = abs(c[0] - ox) + abs(c[1] - oy)
            if d > best:
                best = d
                target = c
        dx = sgn(sx, target[0])
        dy = sgn(sy, target[1])
