            if best_score is None or score < best_score:
                best_score = score
                best = (x, y)
        if best is None:
            opp = observation.get("opponent_territory") or []
            if opp:
                best = pos(opp[0], (sx, sy))
            else:
                return [0, 0]
        dx = sgn(sx, best[0])
        dy = sgn(sy, best[1])
        return clamp_move(dx, dy)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = None
        best_score = None
        for item in resources:
            x, y = pos(item, None)
            if x is None:
                continue
            score = abs(x - sx) + abs(y - sy)
            if best_score is None or score < best_score:
                best_score = score
                best = (x, y)
        if best is not None:
            dx = sgn(sx, best[0])
            dy = sgn(sy, best[1])
            return clamp_move(dx, dy)

    # Fallback: move away from opponent if possible, else hold.
    dx = sgn(ox, sx)
    dy = sgn(oy, sy)
    if dx == 0 and dy == 0:
        return [0, 0]
    return clamp_move(dx, dy)

